  <div class="field-wrapper" ref="wrapper">
    <input
      :id="id"
      :placeholder="placeholder"
      @focus="showHint"
      @blur="hideHint"
      autocomplete="off"
    />
    <div class="typing-hint" />
  </div>
</template>

