## 1️⃣  Minimal vanilla‑JS example (300 wpm)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Form with fast typing hint</title>
  <style>
    .field-wrapper { position: relative; margin-bottom: 1.5rem; }
    .typing-hint   { position: absolute; left: 0; top: -1.8rem; pointer-events: none; }
  </style>
</head>
<body>

<form id="demoForm">
  <div class="field-wrapper">
    <input type="email" id="email" placeholder="Email" autocomplete="off">
    <div id="emailHint" class="typing-hint"></div>
  </div>

  <div class="field-wrapper">
    <input type="password" id="pwd" placeholder="Password" autocomplete="off">
    <div id="pwdHint" class="typing-hint"></div>
  </div>

  <button type="submit">Submit</button>
</form>

<script type="module">
  // -------------------------------------------------
  // Helper – create the SVG and start the animation
  // -------------------------------------------------
  async function makeHint({targetDiv, text, options = {}}) {
    const {fontColor, fontFamily, fontSize, typingSpeed} = options;

    // 1️⃣  Create the SVG (the library returns an <svg> element)
    const svg = await createTypingSVG({
      text,
      fontColor,
      fontFamily,
      fontSize,
      typingSpeed,          // <-- we pass 300 here
      // No delayBeforeStart → default (1000 ms) is used
    });

    // 2️⃣  Insert it into the page
    targetDiv.innerHTML = '';
    targetDiv.appendChild(svg);

    // 3️⃣  Optional: set cursor blink rate (keep the default 500 ms)
    await setCursorBlinkRate({svgId: svg.id, blinkRate: '500'});

    // 4️⃣  Set the typing speed (again) – this also lets us override the delay
    //    Since we want the default delay, we omit delayBeforeStart.
    await setTypingAnimation({typingSpeed: typingSpeed ?? 300});

    return svg.id;
  }

  // -------------------------------------------------
  // Attach listeners to each input
  // -------------------------------------------------
  const fields = [
    {
      input: document.getElementById('email'),
      hintDiv: document.getElementById('emailHint'),
      hintText: 'Enter the email you use for your account.',
      options: {fontColor: '#0066cc', fontSize: 14, typingSpeed: 300},
    },
    {
      input: document.getElementById('pwd'),
      hintDiv: document.getElementById('pwdHint'),
      hintText: 'Choose a strong password (8+ characters).',
      options: {fontColor: '#0066cc', fontSize: 14, typingSpeed: 300},
    },
  ];

  fields.forEach(async ({input, hintDiv, hintText, options}) => {
    let svgId = null;

    input.addEventListener('focus', async () => {
      if (!svgId) {
        svgId = await makeHint({targetDiv: hintDiv, text: hintText, options});
      }
      hintDiv.style.display = 'block';
    });

    input.addEventListener('blur', () => {
      hintDiv.style.display = 'none';
    });
  });
</script>
</body>
</html>
```

### What changed?

| Change | Reason |
|--------|--------|
| `typingSpeed: 300` (passed to `createTypingSVG` and `setTypingAnimation`) | Sets the animation to **300 wpm** (≈ 5 characters per ms for typical English text). |
| **No** `delayBeforeStart` argument | The library’s default delay (1 000 ms) is used automatically, as you requested. |
| `setCursorBlinkRate` left at the default `500 ms` blink interval (you can change it if you like). |

