## 2️⃣  React functional component (300 wpm)

```jsx
import { useEffect, useRef } from 'react';
import {
  createTypingSVG,
  setTypingAnimation,
  setCursorBlinkRate,
} from './typingSvgHelpers';   // adjust import path

export function TypingHintInput({
  id,
  placeholder,
  hint,
  options = { fontColor: '#0066cc', fontSize: 14, typingSpeed: 300 },
}) {
  const wrapperRef = useRef(null);
  const svgIdRef = useRef(null);

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const hintDiv = wrapper.querySelector('.typing-hint');

    async function initHint() {
      const svg = await createTypingSVG({
        text: hint,
        ...options,               // typingSpeed = 300 here
        // delayBeforeStart omitted → default (1000 ms) used
      });
      hintDiv.innerHTML = '';
      hintDiv.appendChild(svg);
      svgIdRef.current = svg.id;

      await setCursorBlinkRate({ svgId: svg.id, blinkRate: '500' });
      await setTypingAnimation({ typingSpeed: options.typingSpeed });
    }

    initHint();
  }, [hint, options]);

  const showHint = () => {
    wrapperRef.current.querySelector('.typing-hint').style.display = 'block';
  };
  const hideHint = () => {
    wrapperRef.current.querySelector('.typing-hint').style.display = 'none';
  };

  return (
    <div className="field-wrapper" ref={wrapperRef} style={{ position: 'relative' }}>
      <input
        id={id}
        placeholder={placeholder}
        onFocus={showHint}
        onBlur={hideHint}
        autoComplete="off"
      />
      <div className="typing-hint" style={{ position: 'absolute', top: '-1.8rem', left: 0 }} />
    </div>
  );
}
```

*All options are the same as the vanilla example – the only required change is `typingSpeed: 300`.*

